class FamilyAgentMessageSerializer(serializers.ModelSerializer):
    run = serializers.SerializerMethodField()
    run_status = serializers.SerializerMethodField()
    run_error_text = serializers.SerializerMethodField()
    proposals = serializers.SerializerMethodField()
    memory_suggestions = serializers.SerializerMethodField()
    attachments = FamilyAgentMessageAttachmentSerializer(many=True, read_only=True)

    class Meta:
        model = FamilyAgentMessage
        fields = [
            "id",
            "thread",
            "author_user",
            "role",
            "text",
            "status",
            "citations_json",
            "context_json",
            "run",
            "run_status",
            "run_error_text",
            "attachments",
            "proposals",
            "memory_suggestions",
            "created_at",
            "updated_at",
        ]
        read_only_fields = fields

    def _get_resolved_run(self, obj: FamilyAgentMessage) -> FamilyAgentRun | None:
        if obj.run_id is not None:
            return obj.run
        return obj.triggered_runs.order_by("-created_at").first()

    def get_run(self, obj: FamilyAgentMessage) -> str | None:
        run = self._get_resolved_run(obj)
        if run is None:
            return None
        return str(run.id)

    def get_run_status(self, obj: FamilyAgentMessage) -> str | None:
        run = self._get_resolved_run(obj)
        if run is None:
            return None
        return run.status

    def get_run_error_text(self, obj: FamilyAgentMessage) -> str:
        run = self._get_resolved_run(obj)
        if run is None:
            return ""
        return run.error_text

    def get_proposals(self, obj: FamilyAgentMessage) -> list[dict]:
        if obj.run_id is None or obj.run is None:
            return []
        proposals = obj.run.proposals.all().order_by("created_at")
        return list(FamilyAgentProposalSerializer(proposals, many=True).data)

    def get_memory_suggestions(self, obj: FamilyAgentMessage) -> list[dict]:
        if obj.run_id is None or obj.run is None:
            return []
        suggestions = obj.run.memory_suggestions.all().order_by("created_at")
        return list(FamilyAgentMemorySuggestionSerializer(suggestions, many=True).data)


class FamilyAgentMessageCreateSerializer(serializers.Serializer):
    thread_id = serializers.UUIDField(required=False)
    text = serializers.CharField(
        allow_blank=True,
        required=False,
        default="",
        trim_whitespace=True,
    )
    context = serializers.JSONField(required=False, default=dict)  # type: ignore[assignment]
    images = serializers.ListField(
        child=serializers.FileField(),
        required=False,
        allow_empty=True,
        write_only=True,
        default=list,
    )

    def to_internal_value(self, data):
        if hasattr(data, "getlist"):
            mutable = data.copy()
            mutable.setlist("images", data.getlist("images"))
            data = mutable
        return super().to_internal_value(data)

    def validate_context(self, value: object) -> dict:
        if value in (None, ""):
            return {}
        if isinstance(value, str):
            try:
                parsed = json.loads(value)
            except json.JSONDecodeError as exc:
                raise serializers.ValidationError(
                    "Context must be valid JSON."
                ) from exc
            if not isinstance(parsed, dict):
                raise serializers.ValidationError("Context must be a JSON object.")
            return parsed
        if not isinstance(value, dict):
            raise serializers.ValidationError("Context must be a JSON object.")
        return value

    def validate_images(self, value: list) -> list:
        if len(value) > 4:
            raise serializers.ValidationError("You can attach up to 4 images.")

        for image in value:
            content_type = (
                getattr(image, "content_type", None) or "application/octet-stream"
            )
            if content_type not in settings.ALLOWED_IMAGE_TYPES:
                raise serializers.ValidationError(
                    f"Unsupported image type: {content_type}"
                )

            file_size = getattr(image, "size", None) or 0
            if file_size > settings.MAX_IMAGE_SIZE:
                max_mb = settings.MAX_IMAGE_SIZE / (1024 * 1024)
                raise serializers.ValidationError(
                    f"Images must be {max_mb:.0f}MB or smaller."
                )
        return value

    def validate(self, attrs: dict) -> dict:
        text = str(attrs.get("text") or "").strip()
        images = attrs.get("images") or []
        if not text and not images:
            raise serializers.ValidationError(
                "Provide message text or at least one image."
            )
        attrs["text"] = text
        attrs["context"] = attrs.get("context") or {}
        attrs["images"] = images
        return attrs


