from __future__ import annotations

import base64
import io
import logging
import mimetypes
import os
import re
import uuid
from typing import Any
from urllib.parse import urlsplit, urlunsplit

import boto3
from botocore.client import Config
from django.conf import settings
from django.core.files.base import ContentFile
from django.core.files.storage import storages
from PIL import Image, UnidentifiedImageError

logger = logging.getLogger(__name__)

DEFAULT_DOWNLOAD_EXPIRY_SECONDS = 900
THUMBNAIL_MAX_DIMENSION = 720


class PrivateMediaStorageService:
    _presign_clients: dict[tuple[str, str, str, str, str], Any] = {}

    @staticmethod
    def _storage(storage_alias: str = "privateMedia"):
        return storages[storage_alias]

    @staticmethod
    def _sanitize_filename(filename: str | None) -> str:
        basename = os.path.basename(filename or "upload")
        sanitized = re.sub(r"[^A-Za-z0-9._-]", "_", basename)
        return sanitized or "upload"

    @staticmethod
    def _resolve_extension(*, filename: str, content_type: str) -> str:
        extension = os.path.splitext(filename)[1].lower()
        if extension:
            return extension

        guessed_extension = mimetypes.guess_extension(content_type or "")
        if guessed_extension:
            return guessed_extension
        return ".jpg"

    @staticmethod
    def _is_local_development_host(hostname: str | None) -> bool:
        if not hostname:
            return False
        normalized = hostname.strip("[]").lower()
        return normalized in {
            "localhost",
            "minio",
            "host.docker.internal",
            "0.0.0.0",  # noqa: S104
            "127.0.0.1",
        }

    @classmethod
    def _resolve_endpoint_for_request(
        cls,
        endpoint_url: str,
        request_host: str | None = None,
    ) -> str:
        if not request_host:
            return endpoint_url

        endpoint_parts = urlsplit(endpoint_url)
        if not cls._is_local_development_host(endpoint_parts.hostname):
            return endpoint_url

        request_parts = urlsplit(
            request_host if "://" in request_host else f"//{request_host}"
        )
        request_hostname = request_parts.hostname
        if not request_hostname:
            return endpoint_url

        if endpoint_parts.port is None:
            netloc = request_hostname
        else:
            netloc = f"{request_hostname}:{endpoint_parts.port}"

        return urlunsplit(
            (
                endpoint_parts.scheme,
                netloc,
                endpoint_parts.path,
                endpoint_parts.query,
                endpoint_parts.fragment,
            )
        )

    @classmethod
    def _resolve_presign_client_config(
        cls,
        *,
        request_host: str | None = None,
    ) -> tuple[str, str, str]:
        endpoint_url = (
            settings.AWS_PRIVATE_MEDIA_PUBLIC_ENDPOINT_URL
            or settings.AWS_PRIVATE_MEDIA_ENDPOINT_URL
        )
        if not endpoint_url:
            raise ValueError("Private media storage endpoint URL is not configured.")

        return (
            cls._resolve_endpoint_for_request(endpoint_url, request_host=request_host),
            settings.AWS_PRIVATE_MEDIA_BUCKET_NAME,
            "path",
        )

    @classmethod
    def _get_presign_client(
        cls,
        *,
        endpoint_url: str,
        addressing_style: str,
    ) -> Any:
        cache_key = (
            endpoint_url,
            settings.AWS_PRIVATE_MEDIA_BUCKET_NAME,
            settings.AWS_PRIVATE_MEDIA_REGION_NAME,
            settings.AWS_PRIVATE_MEDIA_ACCESS_KEY_ID or "",
            settings.AWS_PRIVATE_MEDIA_SECRET_ACCESS_KEY or "",
        )
        cached_client = cls._presign_clients.get(cache_key)
        if cached_client is not None:
            return cached_client

        client = boto3.client(
            "s3",
            endpoint_url=endpoint_url,
            aws_access_key_id=settings.AWS_PRIVATE_MEDIA_ACCESS_KEY_ID,
            aws_secret_access_key=settings.AWS_PRIVATE_MEDIA_SECRET_ACCESS_KEY,
            region_name=settings.AWS_PRIVATE_MEDIA_REGION_NAME,
            config=Config(
                signature_version="s3v4",
                s3={"addressing_style": addressing_style},
            ),
        )
        cls._presign_clients[cache_key] = client
        return client

    @classmethod
    def save_image_attachment(
        cls,
        file_obj: Any,
        *,
        thread_id: str,
        message_id: str,
        display_order: int,
        storage_alias: str = "privateMedia",
    ) -> dict[str, Any]:
        content_type = (
            getattr(file_obj, "content_type", None)
            or mimetypes.guess_type(getattr(file_obj, "name", "") or "")[0]
            or "application/octet-stream"
        )
        if content_type not in settings.ALLOWED_IMAGE_TYPES:
            raise ValueError(f"Unsupported image type: {content_type}")

        file_size = getattr(file_obj, "size", None) or 0
        if file_size > settings.MAX_IMAGE_SIZE:
            max_mb = settings.MAX_IMAGE_SIZE / (1024 * 1024)
            raise ValueError(f"Image exceeds maximum size of {max_mb}MB")

        original_filename = cls._sanitize_filename(getattr(file_obj, "name", None))
        extension = cls._resolve_extension(
            filename=original_filename,
            content_type=content_type,
        )
        unique_stem = f"{display_order}-{uuid.uuid4()}"
        object_key = f"family-agent/{thread_id}/{message_id}/{unique_stem}{extension}"

        file_bytes = file_obj.read()
        try:
            file_obj.seek(0)
        except Exception as exc:  # noqa: BLE001
            logger.debug("Unable to rewind upload stream: %s", exc)

        storage = cls._storage(storage_alias)
        path = storage.save(object_key, ContentFile(file_bytes))

        width: int | None = None
        height: int | None = None
        thumbnail_path: str | None = None

        try:
            with Image.open(io.BytesIO(file_bytes)) as image:
                image.load()
                width, height = image.size

                thumbnail = image.copy()
                if thumbnail.mode not in {"RGB", "L"}:
                    thumbnail = thumbnail.convert("RGB")
                elif thumbnail.mode == "L":
                    thumbnail = thumbnail.convert("RGB")
                thumbnail.thumbnail(
                    (THUMBNAIL_MAX_DIMENSION, THUMBNAIL_MAX_DIMENSION),
                    Image.Resampling.LANCZOS,
                )

                thumbnail_buffer = io.BytesIO()
                thumbnail.save(thumbnail_buffer, format="JPEG", quality=85)
                thumbnail_key = (
                    f"family-agent/{thread_id}/{message_id}/thumbs/{unique_stem}.jpg"
                )
                thumbnail_path = storage.save(
                    thumbnail_key,
                    ContentFile(thumbnail_buffer.getvalue()),
                )
        except (UnidentifiedImageError, OSError, ValueError) as exc:
            logger.warning(
                "Could not build planner image thumbnail for %s: %s",
                original_filename,
                exc,
            )

        return {
            "storage_alias": storage_alias,
            "object_key": path,
            "thumbnail_object_key": thumbnail_path,
            "original_filename": original_filename,
            "mime_type": content_type,
            "file_size": file_size,
            "width": width,
            "height": height,
        }

    @classmethod
    def delete_object(
        cls,
        object_key: str | None,
        *,
        storage_alias: str = "privateMedia",
    ) -> None:
        if not object_key:
            return
        try:
            cls._storage(storage_alias).delete(object_key)
        except Exception:
            logger.warning(
                "Failed to delete private media object %s", object_key, exc_info=True
            )

    @classmethod
    def delete_objects(
        cls,
        object_keys: list[str | None],
        *,
        storage_alias: str = "privateMedia",
    ) -> None:
        for object_key in object_keys:
            cls.delete_object(object_key, storage_alias=storage_alias)

    @classmethod
    def generate_download_url(
        cls,
        object_key: str,
        *,
        expires_in: int = DEFAULT_DOWNLOAD_EXPIRY_SECONDS,
        request_host: str | None = None,
        storage_alias: str = "privateMedia",
    ) -> str | None:
        if not object_key:
            return None

        backend = settings.STORAGES.get(storage_alias, {}).get("BACKEND", "")
        if backend == "django.core.files.storage.FileSystemStorage":
            url = cls._storage(storage_alias).url(object_key)
            if url.startswith(("http://", "https://")):
                return url
            site_url = getattr(settings, "SITE_URL", "").rstrip("/")
            return f"{site_url}{url}" if site_url else url

        endpoint_url, bucket_name, addressing_style = (
            cls._resolve_presign_client_config(request_host=request_host)
        )
        client = cls._get_presign_client(
            endpoint_url=endpoint_url,
            addressing_style=addressing_style,
        )
        return client.generate_presigned_url(
            "get_object",
            Params={"Bucket": bucket_name, "Key": object_key},
            ExpiresIn=expires_in,
        )

    @classmethod
    def read_as_data_url(
        cls,
        object_key: str,
        *,
        mime_type: str,
        storage_alias: str = "privateMedia",
    ) -> str:
        with cls._storage(storage_alias).open(object_key, "rb") as source:
            content = source.read()
        encoded = base64.b64encode(content).decode("utf-8")
        return f"data:{mime_type};base64,{encoded}"

