        if not request_host:
            return endpoint_url

        endpoint_parts = urlsplit(endpoint_url)
        if not cls._is_local_development_host(endpoint_parts.hostname):
            return endpoint_url

        request_parts = urlsplit(
            request_host if "://" in request_host else f"//{request_host}"
        )
        request_hostname = request_parts.hostname
        if not request_hostname:
            return endpoint_url

        if endpoint_parts.port is None:
            netloc = request_hostname
        else:
            netloc = f"{request_hostname}:{endpoint_parts.port}"

        return urlunsplit(
            (
