    ) -> tuple[str, str, str]:
        endpoint_url = (
            settings.AWS_PRIVATE_MEDIA_PUBLIC_ENDPOINT_URL
            or settings.AWS_PRIVATE_MEDIA_ENDPOINT_URL
        )
        if not endpoint_url:
            raise ValueError("Private media storage endpoint URL is not configured.")

        return (
            cls._resolve_endpoint_for_request(endpoint_url, request_host=request_host),
