DEFAULT_GROUP_PLAN_DURATION_MINUTES = 150
VALID_GROUP_PLAN_TEMPLATES = {"TEAM_SOCIAL", "DINNER", "HANGOUT", "OTHER"}
GROUP_PLAN_TEMPLATE_ALIASES = {
    "TEAM_SOCIAL_EVENT": "TEAM_SOCIAL",
    "SOCIAL": "TEAM_SOCIAL",
