class FamilyAgentMemoryDetailView(FamilyAgentAccessMixin, APIView):
    def patch(self, request: Request, memory_id: str) -> Response:
        family = self.get_current_family(request)
        item = self._get_item(family, memory_id)
        serializer = FamilyAgentMemoryItemSerializer(
            item,
            data=request.data,
            partial=True,
        )
        serializer.is_valid(raise_exception=True)
        serializer.save(updated_by=cast(User, request.user))
        return Response(serializer.data)

    def delete(self, request: Request, memory_id: str) -> Response:
        family = self.get_current_family(request)
        item = self._get_item(family, memory_id)
        item.is_active = False
        item.updated_by = cast(User, request.user)
        item.save(update_fields=["is_active", "updated_by", "updated_at"])
        return Response(status=status.HTTP_204_NO_CONTENT)

    def _get_item(self, family: FamilyGroup, memory_id: str) -> FamilyAgentMemoryItem:
        try:
            return FamilyAgentMemoryItem.objects.get(
                id=memory_id,
                family=family,
            )
        except FamilyAgentMemoryItem.DoesNotExist as exc:
            raise Http404 from exc


